export function toSentence(array, options = {}) {
  const defaultConnectors = {
    words_connector: ", ",
    two_words_connector: " and ",
    last_word_connector: ", and "
  }

  const connectors = { ...defaultConnectors, ...options }

  if (array.length === 0) {
    return ""
  }

  if (array.length === 1) {
    return array[0]
  }

  if (array.length === 2) {
